<script>
(()=>{const form=document.getElementById('ea-form'),week=document.getElementById('ea-week'),date=document.getElementById('ea-date'),amount=document.getElementById('ea-amount'),purpose=document.getElementById('ea-purpose'),month={{ \Illuminate\Support\Js::from($month->format('Y-m')) }},categories={{ \Illuminate\Support\Js::from($categoryOptions) }};let queue={{ \Illuminate\Support\Js::from(old('entries',[])) }};
function setDate(){date.value=month+'-'+String((Number(week.value)-1)*7+1).padStart(2,'0');}function uuid(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,n=>n.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);}
function render(){const rows=document.getElementById('ea-rows'),inputs=document.getElementById('ea-inputs');rows.replaceChildren();inputs.replaceChildren();let total=0;queue.forEach((r,i)=>{total+=Math.round(Number(r.amount)*100);const tr=document.createElement('tr');['Week '+r.week,r.advance_date,'Rs '+Number(r.amount).toFixed(2),r.purpose].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td);});const td=document.createElement('td'),btn=document.createElement('button');btn.type='button';btn.className='btn btn-sm btn-outline-danger';btn.textContent='Remove';btn.onclick=()=>{queue.splice(i,1);render();};td.append(btn);tr.append(td);rows.append(tr);Object.entries(r).forEach(([k,v])=>{const input=document.createElement('input');input.type='hidden';input.name='entries['+i+']['+k+']';input.value=v;inputs.append(input);});});document.getElementById('ea-save').disabled=!queue.length;document.getElementById('ea-total').textContent='Total: Rs '+(total/100).toFixed(2);}
week.onchange=setDate;document.getElementById('ea-add-row').onclick=()=>{const error=document.getElementById('ea-error');if(!form.elements.recipient_name.value.trim()||!/^\d{1,11}(\.\d{1,2})?$/.test(amount.value)||Number(amount.value)<=0||date.value.slice(0,7)!==month||Math.ceil(Number(date.value.slice(8))/7)!==Number(week.value)||date.value>date.max){error.textContent='Enter person, valid amount, and actual payment date belonging to this week (not in future).';return;}error.textContent='';queue.push({week:Number(week.value),advance_date:date.value,amount:amount.value,purpose:purpose.value,submission_key:uuid()});week.value=String(Math.min(Number(week.value)+1,week.options.length));setDate();amount.value='';purpose.value='';render();};form.onsubmit=e=>{if(!queue.length){e.preventDefault();return;}document.getElementById('ea-save').disabled=true;};document.querySelectorAll('.ea-category').forEach(select=>select.onchange=()=>{const sub=select.closest('form').querySelector('.ea-subcategory');sub.replaceChildren(new Option('Select if applicable',''));(categories[select.value]||[]).forEach(r=>sub.add(new Option(r.name,r.id)));sub.required=(categories[select.value]||[]).length>0;});setDate();render();
@if(old('entries'))document.getElementById('ea-add').showModal();@endif
})();
</script>
